async function renderOfficial(){const res=await api('/social/official');model.offset=res.posts.length;model.latest='official';display(`${page(tr('officialTitle'),tr('officialSubtitle'))}<div id="postStream">${res.posts.length?res.posts.map(postCard).join(''):empty('✧',tr('noPosts'),tr('officialSubtitle'))}</div>${res.hasMore?`<button class="button outlined" data-more-posts>${tr('more')}</button>`:''}`);}
async function renderSaved(){const res=await api('/social/saved');model.offset=res.posts.length;model.latest='saved';display(`${page(tr('saved'))}<div id="postStream">${res.posts.length?res.posts.map(postCard).join(''):empty('♡',tr('noPosts'),tr('noPostsDesc'))}</div>`);}
async function morePosts(){const base=model.latest==='following'?'/social/feed?following=1':model.latest==='feed'?'/social/feed':`/social/${model.latest}`;const res=await api(base+(base.includes('?')?'&':'?')+'offset='+model.offset);model.offset+=res.posts.length;$('#postStream')?.insertAdjacentHTML('beforeend',res.posts.map(postCard).join(''));if(!res.hasMore)$('[data-more-posts]')?.remove();}
async function renderSearch(){display(`${page(tr('search'))}<div class="panel"><label class="field">${tr('searchUser')}<input class="search-input" id="searchInput" type="search" minlength="2" maxlength="24" placeholder="${tr('searchPlaceholder')}" autofocus></label><div id="searchResults" class="search-results">${empty('⌕',tr('search'),tr('searchPlaceholder'))}</div></div>`);}
let searchTimer;async function runSearch(q){const node=$('#searchResults');if(!node)return;if(q.length<2){node.innerHTML='';return;}try{const r=await api('/members/search?q='+encodeURIComponent(q));if(!$('#searchResults'))return;node.innerHTML=r.profiles.length?r.profiles.map(p=>`<button class="search-row" data-profile="${esc(p.id)}">${avatar(p)}<div><strong>${esc(p.name)} ${badge(p)}</strong><small>@${esc(p.username||'')}</small></div><span class="suffix">↗</span></button>`).join(''):empty('⌕',tr('noResults'),'');}catch(e){node.innerHTML=esc(e.message)}}
async function renderProfile(id){if(location.pathname!=='/profil/'+id)history.replaceState({route:'profile'},'','/profil/'+encodeURIComponent(id));const r=await api('/social/profiles/'+encodeURIComponent(id)),p=r.profile,own=id===model.me.id;model.currentProfile=p;
 const posts=p.posts||[],buttons=own?`<button class="button outlined small" data-edit-profile>${tr('editProfile')}</button><button class="button outlined small" data-menu-toggle>☰ Menü</button>`:`<button class="button primary small" data-follow="${esc(id)}">${p.followingUser?tr('unfollow'):tr('follow')}</button><button class="button outlined small" data-message-user="${esc(id)}">${tr('sendMessage')}</button><button class="button outlined small" data-report="user:${esc(id)}">${tr('report')}</button><button class="button outlined small" data-block-user="${esc(id)}">${tr('block')}</button>`;
 display(`${model.previousRoute==='messages'?'<button class="button outlined small" data-return-chat>← Zurück zum Chat</button>':''}<div class="profile-top"><div class="avatar-edit-wrap">${avatar(p,'big')}${own?'<button class="avatar-upload-plus" data-upload-avatar aria-label="Profilbild hochladen">＋</button>':''}</div><div class="profile-title"><h1>${esc(p.username)} ${badge(p)}</h1><div class="split-actions">${buttons}</div><div class="profile-stats"><span><strong>${formatCount(posts.length)}</strong> ${tr('posts')}</span><button class="profile-stat-button" data-follow-list="followers:${esc(id)}"><strong>${formatCount(p.followers)}</strong> ${tr('followers')}</button><button class="profile-stat-button" data-follow-list="following:${esc(id)}"><strong>${formatCount(p.following)}</strong> ${tr('following')}</button><span><strong>${formatCount(p.totalLikes||0)}</strong> Likes</span></div><strong>${esc(p.name||p.username)}</strong> ${p.role==='owner'?'<span class="tag ceo-tag">CEO</span>':p.role?'<span class="tag team-tag">Kennely Team</span>':''}<p>${esc(p.bio||'')}</p><span class="tiny">${esc(p.city||'')}</span></div></div>${own?`<div class="filter-row" style="margin-top:20px"><button class="button primary small" data-go="create">＋ ${tr('newPost')}</button><button class="button outlined small" data-new-story>${tr('newStory')}</button></div>`:''}<div class="profile-grid">${posts.map(x=>`<button data-open-post="${esc(x.id)}">${x.mediaId?(x.mediaMime?.startsWith('video/')?`<video src="${socialImg(x.mediaId)}" preload="none" muted playsinline></video><span class="reel-corner">▶</span>`:`<img loading="lazy" src="${socialImg(x.mediaId)}" alt="">`):`<span class="txt-tile">${esc(x.caption.slice(0,100))}</span>`}</button>`).join('')}</div>${!posts.length?empty('✧',tr('noPosts'),tr('noPostsDesc')):''}`);
}
async function openPost(id){const card=document.querySelector(`[data-post="${CSS.escape(id)}"]`);if(card){openModal(card.outerHTML);return;}const data=await api('/social/posts/'+encodeURIComponent(id));if(data.post)openModal(postCard(data.post));else toast(tr('unavailable'));}
function showComposer(kind='post'){const story=kind==='story';model.previewMedia=null;openModal(`<h2>${story?tr('newStory'):tr('newPost')}</h2><p>${story?tr('storyExpire'):tr('photoReview')}</p><form id="composeForm" class="column"><label class="field">${story?tr('textStory'):tr('writeCaption')}<textarea name="text" maxlength="${story?320:1500}" placeholder="${story?tr('textStory'):tr('writeCaption')}"></textarea></label><div class="photo-picker"><input class="file-visually-hidden" id="newPhoto" type="file" accept="image/png,image/jpeg,image/webp"><label for="newPhoto" class="photo-picker-plus" role="button" aria-label="Foto auswählen" tabindex="0">+</label><span class="field-hint">Tippe auf +, um ein Foto auszuwählen.</span></div><div id="photoPreview"></div>${!story?`<label class="field">${tr('visibility')}<select name="visibility"><option value="public">${tr('public')}</option><option value="followers">${tr('followersOnly')}</option></select></label>`:`<label class="field">${tr('background')}<input type="color" name="background" value="#6436d8"></label>`}<button class="button primary" type="submit">${tr('publish')}</button></form>`);$('#composeForm').dataset.kind=kind;}
async function compressFile(file,maxBytes=640000){const source=await createImageBitmap(file);const max=1400;const factor=Math.min(1,max/Math.max(source.width,source.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(source.width*factor));canvas.height=Math.max(1,Math.round(source.height*factor));canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);source.close?.();for(const quality of [.82,.70,.58,.46]){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));if(blob&&blob.size<=maxBytes)return blob;}throw new Error('Photo is too large. Try a smaller picture.');}
async function createContent(form){const kind=form.dataset.kind,fd=new FormData(form),file=$('#newPhoto')?.files?.[0];let mediaId=null;if(file){const video=false;if(video)throw new Error('Nur Fotos sind erlaubt.');
  if(video&&file.size>18000000)throw new Error('Das Video darf maximal 18 MB groß sein.');
  const blob=video?file:await compressFile(file);const result=await api('/social/media?kind='+(kind==='reel'?'post':kind),{method:'POST',headers:{'content-type':video?file.type:'image/jpeg'},body:blob});mediaId=result.id;}
 const data=kind==='story'?{body:String(fd.get('text')||''),mediaId,background:String(fd.get('background')||'#6436d8')}:{caption:String(fd.get('text')||''),mediaId,visibility:String(fd.get('visibility')||'public')};const res=await post(`/social/${kind==='story'?'stories':'posts'}`,data);closeModal();toast(res.pendingReview?tr('notPublished'):tr('success'));navigate('feed');}
async function openStory(id){const list=await api('/social/stories');const s=list.stories.find(x=>x.id===id);if(!s)return toast(tr('unavailable'));openModal(`<h2>@${esc(s.username)}</h2><div class="story-full" style="background:${esc(s.background)}">${s.mediaId?(s.mediaMime?.startsWith('video/')?`<video src="${socialImg(s.mediaId)}" controls playsinline preload="metadata"></video>`:`<img src="${socialImg(s.mediaId)}" alt="">`):''}<strong>${esc(s.body||'')}</strong></div><p>${tr('storyExpire')}</p>`);}
function commentRow(c,postAuthorId){
 const own=c.userId===model.me?.id,canDelete=own||postAuthorId===model.me?.id;
 return `<article class="comment-item ${c.parentId?'is-reply':''}" data-comment-item="${esc(c.id)}"><button type="button" class="comment-avatar" data-profile="${esc(c.userId)}">${avatar(c,'small')}</button><div class="comment-main"><div class="comment-author"><button type="button" class="name-button" data-profile="${esc(c.userId)}">${esc(c.name||c.username)} ${badge(c)}</button><small>@${esc(c.username)} · ${dateTime(c.createdAt)}</small></div><p>${esc(c.body)}</p><div class="comment-tools"><button type="button" class="tiny-btn ${c.liked?'active':''}" data-comment-like="${esc(c.id)}">${c.liked?'♥':'♡'} ${formatCount(c.likes||0)}</button><button type="button" class="tiny-btn" data-comment-reply="${esc(c.id)}" data-reply-to="${esc(c.username)}">Antworten</button></div></div><button type="button" class="comment-more tiny-btn" data-comment-options="${esc(c.id)}" data-can-delete="${canDelete?'1':'0'}" aria-label="Kommentaroptionen">•••</button></article>`;
}
