async function openIdentitySettings(){
 const data=await api('/account/identity');const v=data.identity||{};
 const daysLeft=(timestamp,days)=>{if(!timestamp)return 0;const d=new Date(String(timestamp).replace(' ','T')+(String(timestamp).includes('T')?'':'Z'));if(Number.isNaN(d.getTime()))return 0;return Math.max(0,Math.ceil((d.getTime()+days*86400000-Date.now())/86400000));};
 const usernameWait=daysLeft(v.usernameChangedAt,30),nameWait=daysLeft(v.nameChangedAt,7);
 openModal(`<h2>Benutzername und Anzeigename ändern</h2><p>Du kannst diese Angaben auch als CEO oder Teammitglied selbst bearbeiten. Dein Benutzername ist Pflicht, der Anzeigename freiwillig.</p><form id="identityForm" class="column"><label class="field">Benutzername (10–24 Zeichen)<input name="username" value="${esc(v.username||'')}" minlength="10" maxlength="24" pattern="${USERNAME_INPUT_PATTERN}" title="${USERNAME_PATTERN_HELP}" autocapitalize="off" spellcheck="false" autocomplete="username" ${usernameWait?'readonly aria-readonly="true"':''} required><small>${usernameWait?'Noch '+usernameWait+' Tag(e) gesperrt':'Änderung möglich'} · Letzte Änderung: ${dateTimeFull(v.usernameChangedAt)}</small><small>10–24 Zeichen: Buchstaben, Zahlen, Punkt oder Unterstrich. Groß- und Kleinschreibung ist bei der Eingabe möglich; gespeichert wird klein.</small></label><label class="field">Anzeigename (optional)<input name="name" value="${esc(v.name||'')}" maxlength="32" placeholder="Optional" ${nameWait?'readonly aria-readonly="true"':''}><small>${nameWait?'Noch '+nameWait+' Tag(e) gesperrt':'Änderung möglich'} · Letzte Änderung: ${dateTimeFull(v.nameChangedAt)}</small></label><button type="submit" class="button primary">Änderungen speichern</button></form><p class="tiny">Die Zeitlimits werden vom Server geprüft.</p>`);
}
function bubbleHtml(m){
 const mine=m.senderId===model.me?.id;
 const reactions=(m.reactions||[]).map(r=>`<span title="${r.userId===model.me?.id?'Deine Reaktion':'Reaktion'}">${esc(r.emoji)}</span>`).join('');
 return `<div class="bubble-row ${mine?'mine':''}"><div class="bubble ${mine?'mine':''}" data-bubble="${esc(m.id)}" title="Doppeltippen für ❤️">${esc(m.body)}${reactions?`<div class="emoji-reactions">${reactions}</div>`:''}</div><button class="react-trigger" data-react-picker="${esc(m.id)}" aria-label="Mit Emoji reagieren">♡</button></div>`;
}
async function reactToMessage(id,emoji='❤️'){
 const thread=model.activeThread;if(!thread)return;
 const bubble=document.querySelector(`[data-bubble="${CSS.escape(id)}"]`);
 if(bubble){const row=bubble.querySelector('.emoji-reactions')||document.createElement('div');row.className='emoji-reactions';row.innerHTML=`<span>${esc(emoji)}</span>`;bubble.append(row);}
 try{await post('/social/dm/'+encodeURIComponent(thread)+'/messages/'+encodeURIComponent(id)+'/react',{emoji});model.threadSignature=null;}
 catch(error){toast(error.message);refreshCurrentThread().catch(()=>{});}
}
