document.addEventListener('change',async e=>{if(e.target.id==='privateToggle'){const input=e.target;input.disabled=true;try{const r=await patch('/account/privacy',{isPrivate:input.checked});model.me.isPrivate=r.isPrivate;toast(r.isPrivate?'Dein Profil ist jetzt privat.':'Dein Profil ist jetzt öffentlich.');}catch(error){input.checked=!input.checked;toast(error.message)}finally{input.disabled=false;}}});
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const submit=form.querySelector('button[type=submit]');if(submit)submit.disabled=true;const fd=new FormData(form);try{
 if(form.id==='staffDetailForm'){const detail=await api('/admin/users/'+encodeURIComponent(form.dataset.id)+'?reason='+encodeURIComponent(String(fd.get('reason')||'')));const u=detail.user;$('#staffDetailResult').innerHTML=`<div class="account-details"><div><span>Benutzername</span><strong>@${esc(u.username)}</strong></div><div><span>Anzeigename</span><strong>${esc(u.name)}</strong></div>${u.email?`<div><span>E-Mail (vertraulich)</span><strong>${esc(u.email)}</strong></div>`:''}<div><span>Registriert</span><strong>${dateTimeFull(u.createdAt)}</strong></div><div><span>Letzter Login</span><strong>${u.lastLoginAt?dateTimeFull(u.lastLoginAt):'Keine Angabe'}</strong></div><div><span>E-Mail bestätigt</span><strong>${u.emailVerifiedAt?'Ja':'Nein'}</strong></div><div><span>Konto</span><strong>${u.banned?'Gesperrt':'Aktiv'}</strong></div><div><span>Teamrolle</span><strong>${esc(u.role||'Nutzer')}</strong></div></div>`;}
 else if(form.id==='avatarReviewForm'){const id=form.dataset.id,decision=form.dataset.decision;const note=String(fd.get('reason')||'');await post('/admin/photos/'+encodeURIComponent(id)+'/review',{decision,reason:note,moderation:'none'});closeModal();toast(decision==='approved'?'Profilfoto freigegeben':'Profilfoto abgelehnt');renderAdmin();}
 else if(form.id==='avatarForwardForm'){await post('/admin/photos/'+encodeURIComponent(form.dataset.id)+'/forward',{toStaffId:fd.get('toStaffId'),note:fd.get('note')});closeModal();toast('An das Team weitergeleitet.');renderAdmin();}
 else if(form.id==='reviewForm'){const kind=form.dataset.reviewKind,id=form.dataset.reviewId,status=form.dataset.reviewStatus,reason=String(fd.get('reason')||'');if(kind==='content')await post('/social/admin/content-review',{id,type:form.dataset.contentType,status,reason});if(kind==='media')await post('/social/admin/review',{mediaId:id,status,reason});if(kind==='report')await post('/social/admin/report',{reportId:id,status,note:reason,removeContent:fd.has('removeContent')});if(kind==='appeal')await post('/social/admin/appeal',{appealId:id,status});if(kind==='user')await post('/admin/moderate',{userId:id,action:status,reason,feature:fd.get('feature')||'chat',days:Math.max(1,Math.min(365,Number(fd.get('days')||7))),notifyEmail:fd.has('notifyEmail')});closeModal();toast(tr('success'));renderAdmin();}
 else if(form.id==='authForm'){const data={email:fd.get('email'),password:fd.get('password')};if(form.dataset.kind==='register'){const dob=fd.get('birthDate'),cut=cutoff();if(dob>cut)throw new Error(tr('adultOnly'));Object.assign(data,{name:fd.get('name'),username:fd.get('username'),birthDate:dob,gender:fd.get('gender'),city:'',adult:fd.has('adult'),terms:fd.has('terms')});}const r=await post('/auth/'+(form.dataset.kind==='register'?'register':'login'),data);closeModal();mountUser(r.user);}
 else if(form.id==='composeForm'){await createContent(form);}
 else if(form.id==='commentForm'){const res=await post(`/social/posts/${form.dataset.id}/comments`,{body:fd.get('body'),parentId:fd.get('parentId')||null});await openComments(form.dataset.id);toast(res.pendingReview?'Kommentar wartet auf Freigabe.':'Kommentar gesendet.');}
 else if(form.id==='reportForm'){const type=form.dataset.targetType,id=form.dataset.targetId;if(!await ask(tr('confirmReport'),tr('reason')))return;await post('/social/report',{type,id,reason:fd.get('reason'),details:fd.get('details')});closeModal();toast(tr('reportSent'));}
 else if(form.id==='sendMessageForm'){const text=String(fd.get('body')||'').trim(),id=form.dataset.thread;if(!text)throw new Error('Nachricht ist leer.');const list=$('#messageScroll');const bubble=document.createElement('div');bubble.className='bubble mine sending';bubble.textContent=text;bubble.setAttribute('aria-label','Wird gesendet');list?.append(bubble);if(list)list.scrollTop=list.scrollHeight;form.reset();
  try{await post('/social/dm/'+encodeURIComponent(id)+'/send',{body:text});bubble.classList.remove('sending');bubble.removeAttribute('aria-label');model.threadSignature=null;const preview=document.querySelector('[data-thread="'+CSS.escape(id)+'"] .names small');if(preview)preview.textContent=text;await refreshCurrentThread().catch(()=>{});}
  catch(error){bubble.remove();form.querySelector('[name=body]').value=text;throw error;}}

 else if(form.id==='termForm'){const term=String(fd.get('term')||'');const action=String(fd.get('action'));if(!await ask('Wortliste bearbeiten?',`${term} → ${action}`,'Änderung bestätigen'))return;await post('/admin/terms',{term,action});toast('Regel gespeichert');renderAdmin();}
 else if(form.id==='permissionsForm'){const scope=fd.get('scope'),role=String(fd.get('role')),userId=String(fd.get('userId')||'').trim();const capability=String(fd.get('capability')),enabled=fd.get('enabled')==='true';if(scope==='user'&&!userId)throw new Error('Benutzer-ID benötigt');if(!await ask('Berechtigung wirklich ändern?',`${scope==='user'?userId:role}: ${capability} → ${enabled?'Erlauben':'Verweigern'}`,'Ja, speichern'))return;await post('/admin/permissions',{role,capability,enabled,...(scope==='user'?{userId}:{})});toast('Berechtigung gespeichert');renderAdmin();}
 else if(form.id==='staffIdentityForm'){const id=form.dataset.id,username=String(fd.get('username')||'').trim(),name=String(fd.get('name')||'').trim();if(!username&&!name)throw new Error('Mindestens einen Wert eingeben');if(!await ask('Profildaten wirklich ändern?','Diese Änderung wird im Team-Protokoll gespeichert.','Bestätigen'))return;if(id===model.me.id){await patch('/account/identity',{...(username?{username}:{}),...(name!==undefined?{name}:{})});const latest=await api('/me');model.me=latest.user;shell();}
 else await post('/admin/identity',{userId:id,...(username?{username}:{}),...(name?{name}:{})});closeModal();toast('Profildaten geändert');}
 else if(form.id==='staffLabelForm'){const id=form.dataset.id;if(!await ask('Label vergeben?',fd.get('label'),'Bestätigen'))return;await post('/admin/labels',{userId:id,label:fd.get('label'),color:fd.get('color'),action:'add'});closeModal();toast('Label gespeichert');}
 else if(form.id==='identityForm'){const current=await api('/account/identity'),u=current.identity;const username=String(fd.get('username')||'').trim().toLowerCase(),name=String(fd.get('name')||'').trim();const update={};if(username!==u.username)update.username=username;if(name!==(u.name||''))update.name=name;if(!Object.keys(update).length){closeModal();toast('Keine Änderungen.');return;}
 if(!await ask('Profilidentität ändern?','Für Nutzernamen gilt eine 30-Tage-Frist, für Anzeigenamen eine 7-Tage-Frist.','Änderung bestätigen'))return;
 await patch('/account/identity',update);const newUser=await api('/me');model.me=newUser.user;closeModal();shell();toast('Profilidentität gespeichert.');if(model.route==='profile')renderProfile(model.me.id);}
 else if(form.id==='privacyForm'){await patch('/account/privacy/preferences',{isPrivate:fd.has('isPrivate'),messagePolicy:fd.get('messagePolicy'),followVisibility:fd.get('followVisibility'),commentPolicy:fd.get('commentPolicy'),discoverable:fd.has('discoverable')});model.me.isPrivate=fd.has('isPrivate');toast('Privatsphäre gespeichert.');}
 else if(form.id==='settingsForm'){await patch('/settings',{locale:'de',theme:fd.get('theme'),chatLocale:'de',notifyMessages:fd.has('notifyMessages')});setTheme(fd.get('theme'),false);setLang('de',false);toast(tr('success'));}
 else if(form.id==='editProfileForm'){await patch('/profile',{bio:fd.get('bio'),city:fd.get('city'),gender:model.me.gender||'divers',lookingFor:'alle',intent:'offen',interests:model.me.interests||[],visible:true});model.me.bio=String(fd.get('bio'));model.me.city=String(fd.get('city'));closeModal();renderProfile(model.me.id);}
 else if(form.id==='passwordChangeForm'){await post('/account/change-password',{current:fd.get('current'),next:fd.get('next')});closeModal();toast('Dein Passwort wurde geändert.');}
 else if(form.id==='forgotPasswordForm'){await post('/auth/request-reset',{email:fd.get('email')});closeModal();toast('Falls du ein Konto hast, erhältst du einen Link.');}
 else if(form.id==='resetPasswordForm'){await post('/auth/reset',{token:fd.get('token'),password:fd.get('password')});closeModal();toast('Passwort geändert. Bitte melde dich an.');}
 else if(form.id==='avatarForm'){const file=fd.get('photo'),blob=await compressFile(file,325000);await api('/photos',{method:'POST',headers:{'content-type':'image/jpeg'},body:blob});closeModal();toast(tr('notPublished'));}
 else if(form.id==='appealForm'){await post('/social/appeal',{reason:fd.get('reason')});toast(tr('success'));form.reset();}
 else if(form.id==='ticketForm'){await post('/support',{category:fd.get('category'),subject:fd.get('subject'),body:fd.get('body')});closeModal();navigate('support');}
 else if(form.id==='ticketReply'){await post('/support/'+form.dataset.id+'/reply',{body:fd.get('body')});openTicket(form.dataset.id);}
 else if(form.id==='forwardMediaForm'){await post('/social/admin/forward',{mediaId:form.dataset.id,toStaffId:fd.get('toStaffId'),note:fd.get('note')});closeModal();toast('An das Team weitergeleitet.');renderAdmin();}
 else if(form.id==='legalRequestForm'){await post('/legal-requests',{reference:fd.get('reference'),authority:fd.get('authority'),legalBasis:fd.get('legalBasis'),scope:fd.get('scope')});toast('Anfrage wurde dokumentiert.');renderAdmin();}
 else if(form.id==='teamForm'){if(model.me.role!=='owner')throw new Error('Nur für den CEO');const username=String(fd.get('username')||'').trim().replace(/^@/,'').toLowerCase();const users=await api('/admin/users?q='+encodeURIComponent(username));const usr=users.users.find(x=>x.username?.toLowerCase()===username);if(!usr)throw new Error('Benutzername nicht gefunden.');if(!await ask(tr('assign'),'@'+username+' → '+fd.get('role')))return;await post('/admin/team',{userId:usr.id,role:fd.get('role')});toast(tr('success'));renderAdmin();}
 else if(form.id==='deleteForm'){await post('/account/delete',{password:fd.get('password'),confirm:'KONTO LÖSCHEN'});closeModal();mountGuest();}
 }catch(err){showFormError(err.message||tr('tryAgain'));}finally{if(submit&&submit.isConnected)submit.disabled=false;}});

// Kennely Deutschland: die Oberfläche bleibt vollständig deutsch.
window.addEventListener('popstate',()=>{if(!model.me)return;const path=location.pathname;const mapping={'/':'feed','/home':'feed','/entdecken':'explore','/nachrichten':'messages','/mitteilungen':'notifications','/gespeichert':'saved','/aktivitaeten':'activity','/einstellungen':'settings','/support':'support','/team':'admin'};if(path.startsWith('/profil/'))renderProfile(path.slice(8));else if(path.startsWith('/nachrichten/'))navigate('messages',{pop:true}).then(()=>openThread(decodeURIComponent(path.slice('/nachrichten/'.length)),false));else navigate(mapping[path]||'feed',{pop:true});});
(async()=>{setTheme(model.theme,false);setLang(model.lang,false);try{const r=await api('/me');if(r.user){try{const settings=await api('/settings');model.lang='de';if(settings.preferences?.theme)model.theme=settings.preferences.theme;setTheme(model.theme,false);setLang(model.lang,false);}catch{}mountUser(r.user)}else mountGuest();}catch{document.documentElement.classList.remove('kn-booting');$('#guest').classList.add('hidden');$('#shell').classList.remove('hidden');display('<div class="panel"><h2>Verbindung fehlgeschlagen</h2><p>Dein Anmeldestatus konnte nicht geprüft werden.</p><button class="button primary" data-retry-page>Erneut versuchen</button></div>');}})();

const resetToken=new URLSearchParams(location.search).get('reset');if(resetToken&&/^[a-f0-9]{64}$/.test(resetToken))setTimeout(()=>{resetPasswordModal(resetToken);history.replaceState({},'',location.pathname)},350);

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&model.menuOpen)closeMenu();});

// Touch action: long press opens contextual comment actions, fast double tap hearts a DM.
let commentHold=null;
document.addEventListener('pointerdown',e=>{
 if(e.pointerType!=='touch'||!e.target.closest('.comment-item'))return;
 const row=e.target.closest('.comment-item');clearTimeout(commentHold);
 commentHold=setTimeout(()=>{commentHold=null;const menu=row.querySelector('[data-comment-options]');menu?.click();},620);
},{passive:true});
for(const type of ['pointerup','pointercancel','pointermove','scroll'])document.addEventListener(type,()=>{if(commentHold){clearTimeout(commentHold);commentHold=null;}},{passive:true});
let lastMessageTap={id:null,at:0};
document.addEventListener('pointerup',e=>{
 const bubble=e.target.closest('[data-bubble]');if(!bubble)return;
 if(e.pointerType==='touch'){
  const now=performance.now(),id=bubble.dataset.bubble;
  if(lastMessageTap.id===id&&now-lastMessageTap.at<360){lastMessageTap={id:null,at:0};reactToMessage(id,'❤️');}
  else lastMessageTap={id,at:now};
 }
},{passive:true});
document.addEventListener('dblclick',e=>{
 const bubble=e.target.closest('[data-bubble]');if(bubble&&e.pointerType!=='touch')reactToMessage(bubble.dataset.bubble,'❤️');
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('label[for="newPhoto"],label[for="avatarFile"]')){e.preventDefault();document.getElementById(e.target.htmlFor)?.click();}});
